#include <bits/stdc++.h>
using namespace std;

int main() {
    uint64_t l, r;
    cin >> l >> r;

    vector<uint64_t> lucky = {4, 7};
    size_t i = 0;

    while (lucky.back() < r) {
        uint64_t x = lucky[i++];
        lucky.push_back(x * 10 + 4);
        lucky.push_back(x * 10 + 7);
    }

    __uint128_t sum = 0;
    uint64_t current = l;

    for (uint64_t x : lucky) {
        if (x < current) continue;

        uint64_t end = min(r, x);
        sum += static_cast<__uint128_t>(end - current + 1) * x;

        if (end == r) break;
        current = end + 1;
    }

    if (sum == 0) {
        cout << 0;
    } else {
        string result;
        while (sum > 0) {
            result.push_back('0' + sum % 10);
            sum /= 10;
        }
        reverse(result.begin(), result.end());
        cout << result;
    }

    cout << '\n';
    return 0;
}

