    uint64_t l, r;
    cin >> l >> r;

    vector<uint64_t> lucky;
    queue<uint64_t> q;
    q.push(4);
    q.push(7);

    while (!q.empty()) {
        uint64_t x = q.front();
        q.pop();
        lucky.push_back(x);

        if (x <= 444444444ULL) {
            q.push(x * 10 + 4);
            q.push(x * 10 + 7);
        }
    }

    sort(lucky.begin(), lucky.end());

    uint64_t current = l;
    uint64_t sum = 0;

    for (uint64_t x : lucky) {
        if (current > r) break;
        if (x < current) continue;

        uint64_t end = min(r, x);
        sum += (end - current + 1) * x;
        current = end + 1;
    }

    cout << sum << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using u128 = __uint128_t;

void generateLucky(ull n, vector<ull>& lucky) {
    if (n > 0) lucky.push_back(n);

    if (n <= (numeric_limits<ull>::max() - 4) / 10)
        generateLucky(n * 10 + 4, lucky);
    if (n <= (numeric_limits<ull>::max() - 7) / 10)
        generateLucky(n * 10 + 7, lucky);
}

void print128(u128 n) {
    if (n == 0) {
        cout << 0;
        return;
    }

    string result;
    while (n > 0) {
        result.push_back(char('0' + n % 10));
        n /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull l, r;
    cin >> l >> r;

    vector<ull> lucky;
    generateLucky(0, lucky);
    sort(lucky.begin(), lucky.end());

    ull current = l;
    u128 sum = 0;

    for (ull value : lucky) {
        if (value < current) continue;

        ull end = min(r, value);
        sum += u128(end - current + 1) * value;

        if (end == r) break;
        current = end + 1;
    }

    print128(sum);
    cout << '\n';

    return 0;
}

#include <algorithm>
#include <cstdint>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    uint64_t l, r;
    cin >> l >> r;

    vector<uint64_t> lucky{4, 7};
    vector<uint64_t> level{4, 7};

    while (level.back() < r) {
        vector<uint64_t> nextLevel;
        for (uint64_t x : level) {
            nextLevel.push_back(x * 10 + 4);
            nextLevel.push_back(x * 10 + 7);
        }
        lucky.insert(lucky.end(), nextLevel.begin(), nextLevel.end());
        level = move(nextLevel);
    }

    sort(lucky.begin(), lucky.end());

    unsigned __int128 sum = 0;
    uint64_t current = l;

    for (uint64_t x : lucky) {
        if (x < current) continue;

        uint64_t end = min(r, x);
        sum += static_cast<unsigned __int128>(end - current + 1) * x;

        if (end == r) break;
        current = end + 1;
    }

    if (sum == 0) {
        cout << 0;
    } else {
        string result;
        while (sum > 0) {
            result.push_back(static_cast<char>('0' + sum % 10));
            sum /= 10;
        }
        reverse(result.begin(), result.end());
        cout << result;
    }

    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

void generateLucky(ull value, int depth, vector<ull>& lucky) {
    if (value > 0) lucky.push_back(value);
    if (depth == 10) return;

    generateLucky(value * 10 + 4, depth + 1, lucky);
    generateLucky(value * 10 + 7, depth + 1, lucky);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull l, r;
    cin >> l >> r;

    vector<ull> lucky;
    generateLucky(0, 0, lucky);
    sort(lucky.begin(), lucky.end());

    ull sum = 0;
    ull current = l;

    for (ull x : lucky) {
        if (x < current) continue;

        ull end = min(r, x);
        sum += (end - current + 1) * x;

        if (end == r) break;
        current = end + 1;
    }

    cout << sum << '\n';
    return 0;
}

